// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

contract MoodDiary{

    struct UsersMood{
        string myMood;
        bool haveIEarlyMood;
        uint256 countChangeMyMood;
    }

    mapping(address => UsersMood) private usersMood;

    function writeMood(string memory _mood) public {
        require(bytes(_mood).length > 0 , "Mood can`t be empty!");
        require(!usersMood[msg.sender].haveIEarlyMood, "Mood already exists!");
        usersMood[msg.sender] = UsersMood({
                myMood: _mood,
                haveIEarlyMood: true,
                countChangeMyMood: 0});
        
    }
    
    function changeMood(string memory _mood) public {
        require(usersMood[msg.sender].haveIEarlyMood, "You have not written your mood!");
        require(bytes(_mood).length > 0 , "Mood can`t be empty!");
        usersMood[msg.sender].myMood = _mood;
        usersMood[msg.sender].countChangeMyMood += 1;
    }


    function takeMood() public view returns (string memory){
        require(usersMood[msg.sender].haveIEarlyMood, "You have not write your mood !");
        return usersMood[msg.sender].myMood;
    }

    function clearMood() public{
        require(usersMood[msg.sender].haveIEarlyMood, "No mood to clear!");
        delete usersMood[msg.sender].myMood;
        usersMood[msg.sender].haveIEarlyMood = false;
    }

    function checkHaveIEarlyMood(address _user) public view returns (bool){
        return usersMood[_user].haveIEarlyMood;
    }
    
    function checkCountChangeMyMood(address _user) public view returns (uint256){
        return usersMood[_user].countChangeMyMood;
    }

}

contracts/Warcraft.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract OnChainWarcraft {
    enum Fraction {Alliance, Horde, Undead}

    struct Buildings {
        uint256 sawmillLevel;
        uint256 mineLevel;
        uint256 barracksLevel;
    }

    struct Player {
        bool registered;
        Fraction fraction;
        uint256 wood;
        uint256 stone;
        uint256 gold;
        uint256 warriors;
        Buildings buildings;
        uint256 lastClaimTime;
    }

    mapping(address => Player) public players;

    uint256 public constant INITIAL_WOOD = 100;
    uint256 public constant INITIAL_STONE = 100;
    uint256 public constant INITIAL_GOLD = 100;

    event PlayerRegistered(address indexed player, Fraction fraction);


    modifier onlyRegistered(){
        require(players[msg.sender].registered, "You are not registered!");
        _;
    }

    function register(Fraction _fraction) external {
        require(!players[msg.sender].registered, "Already registered");

        players[msg.sender] = Player({
            registered: true,
            fraction: _fraction,
            wood: INITIAL_WOOD,
            stone: INITIAL_STONE,
            gold: INITIAL_GOLD,
            warriors: 0,
            buildings: Buildings({
                sawmillLevel: 1, 
                mineLevel: 1, 
                barracksLevel: 1}),
            lastClaimTime: block.timestamp
        });

        emit PlayerRegistered(msg.sender, _fraction);
    }


    function getPlayer(address playerAddress) external view  returns(
        bool registered,
        Fraction fraction,
        uint256 wood,
        uint256 stone,
        uint256 gold,
        uint256 warriors,
        uint256 sawmillLevel,
        uint256 mineLevel,
        uint256 barracksLevel
    ){
        Player storage p = players[playerAddress];
        return(
            p.registered,
            p.fraction,
            p.wood,
            p.stone,
            p.gold,
            p.warriors,
            p.buildings.sawmillLevel,
            p.buildings.mineLevel,
            p.buildings.barracksLevel

        );
    }

}
